"""Build readable saved team-game forecast report; no modeling or live writes."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent

def main():
    block=json.loads((HERE/'outlook_2026w6.json').read_text());r=json.loads((HERE/'results.json').read_text())
    lines=['# Fitted team/game outlook v1','','Research-only optional Analyst evidence. Base player projections/defaults are unchanged. Revised historical sources lack contemporaneous provenance; earlier outcomes were inspected. W4/W5 diagnostics and2025 retrospective results do not become pristine validation. Current W6 forecasts are captured before games, but injury/QB uncertainty is unmodeled and no final entry clearance is implied.','','The20-feature Ridge baseline uses own/opponent last-five completed games, scoring, plays, drives, EPA/success, target/carry fractions, rest and home status. Validation-only choice among alpha10/100 selected100. Paired home/away residual draws preserve limited observed game covariance; feasible volume budgets preserve targets+carries<=plays. No market multiplication or team identity feature.','','| Retrospective set | Games | Points MAE | History MAE | Plays MAE | Drives MAE | Win-half-tie Brier |80%score coverage |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for key,label in [('retrospective_2025_normal_weeks','2025W3-17'),('retrospective_2025_sunday_main','2025 Sunday Main'),('already_inspected_2026w4_w5','Known2026W4/W5')]:
        m=r[key];lines.append(f"|{label}|{m['n_games']}|{m['points']['mae']:.2f}|{m['history_points_mae']:.2f}|{m['plays']['mae']:.2f}|{m['drives']['mae']:.2f}|{m['win_half_tie_brier']:.3f}|{m['score_interval80_coverage']:.1%}|")
    lines.extend(['','Scoring slightly trails simple history; this model is a transparent first outlook layer, not a proven projection upgrade. Probability reliability bins in results.json show material gaps (Sunday0.4–0.6 bin forecast51.3%, observed39.1%), despite pooled interval coverage near nominal. No calibrated forward probability claim. Score errors include defense/special teams. Plays/carries include QB and kneel opportunities; possessions are distinct offensive fixed drives represented in PBP, not a full kickoff-to-kickoff drive simulator.','','## Saved W6 forecasts','','Sunday Main includes the ten afternoon games. Thursday SEA–DEN is separately reusable for Captain. All14scheduled games are retained, including London/night games outside Main. Values below are statistical estimates without current injury/QB adjustments. Ties remain separate; table win adds half ties only for comparison.','','| Game | Team | Points | Plays | Possessions | Targets | Carries | Win+half tie | Competitive scoring proxy |','|---|---|---:|---:|---:|---:|---:|---:|---:|'])
    for g in block['games']:
        for team,t in g['teams'].items():
            b=t['central'];lines.append(f"|{g['game_id']}|{team}|{b['points']:.1f}|{b['plays']:.1f}|{b['drives']:.1f}|{b['targets']:.1f}|{b['carries']:.1f}|{t['win_half_tie_probability']:.1%}|{t['capability_branches']['competitive_scoring']['probability']:.1%}|")
    lines.extend(['','## Analyst consumption','','An optional embedded outlook validates hash/source/model/cutoff/kickoff and canonical game identity. Both formats retain shared saved context and conservation audits. Captain uses paired conditional budgets only when supported and within existing ratio bounds; otherwise explicitly retains the old sensitivity fallback. Conditional player fantasy elasticity, receiving concentration and portfolio weights remain design assumptions. Empirical game-event probabilities are neither individual ceilings nor lineup-win probabilities. Missing historical role measurements leave unallocated volume, never fabricated targets.','','The real Sunday preview uses the saved513-player preliminary snapshot with its questionable-player exclusions; Captain uses dated SEA–DEN frozen projections. These previews write no database or live artifacts and do not certify readiness. See classic_preview.json/showdown_preview.json and the separately saved packets.'])
    if (HERE/'example_summary.json').exists():
        summary=json.loads((HERE/'example_summary.json').read_text());lines.append('\n| Offline format | Status | Saved lineups |\n|---|---|---:|')
        for fmt,s in summary.items():lines.append(f"|{fmt}|{s['status']}|{s['lineups']}|")
    lines.extend(['','## Reproduction and validation','','From repository root:','','```sh','PYTHONPATH=. .venv/bin/python -m pytest backend/app/tests/product/test_team_game_outlook.py backend/app/tests/product/test_analyst_scenarios.py backend/app/tests/product/test_captain_analyst.py backend/app/tests/product/test_analyst_packet_routes.py -q','PYTHONPATH=. .venv/bin/python research/team_game_outlook_20261013/run.py','PYTHONPATH=. .venv/bin/python research/team_game_outlook_20261013/examples.py','PYTHONPATH=. .venv/bin/python research/team_game_outlook_20261013/report.py','```','','Full replay should use a new versioned sibling study directory with run.py/SPECIFICATION.md copied there; keep existing outputs and source hashes. The immutable V3 sources remain unchanged. Model fitting/evaluation took '+f"{r['runtime_seconds']:.2f}s"+';4096 empirical draws/game, one20-feature model and two prior-validation choices. Test/model/packet hashes are in delivery_manifest.json. No dependencies installed.','','Next: freeze actual forward predictions and current source clocks, evaluate calibration on new normal-week games, compare market-only and history baselines using captured market snapshots, and model injury/QB/role uncertainty separately. The initial score regression does not beat simple history, so no production promotion is justified.'])
    (HERE/'README.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
